'use client';

import React, { useState, useMemo } from 'react';
import { Plus, Trash2, Filter, ChevronDown, Check, X, AlertCircle, Hash, AlignLeft } from 'lucide-react';
import {
    SegmentRule,
    SegmentField,
    SegmentOperator,
    SegmentRulesPayload,
} from '../types/campaign.types';

// ============================================================================
// CONFIGURATION Constants
// ============================================================================

const FIELDS: { value: SegmentField; label: string; type: 'number' | 'string' | 'select' | 'multi' }[] = [
    { value: 'last_order_days', label: 'Last Order (days ago)', type: 'number' },
    { value: 'total_spend', label: 'Total Spend ($)', type: 'number' },
    { value: 'orders_count', label: 'Total Orders', type: 'number' },
    { value: 'store_id', label: 'Store Identity', type: 'multi' },
    { value: 'consent_status', label: 'Consent Status', type: 'select' },
];

const OPERATORS_FOR_TYPE: Record<'number' | 'string' | 'select' | 'multi', { value: SegmentOperator; label: string }[]> = {
    number: [
        { value: '>', label: 'is greater than' },
        { value: '<', label: 'is less than' },
        { value: '=', label: 'is exactly' },
        { value: '!=', label: 'is not' },
    ],
    string: [
        { value: '=', label: 'equals' },
        { value: 'contains', label: 'contains keyword' },
        { value: '!=', label: 'does not equal' },
    ],
    select: [
        { value: '=', label: 'is' },
        { value: '!=', label: 'is not' },
    ],
    multi: [
        { value: 'in', label: 'is in list' },
        { value: 'not_in', label: 'is not in list' },
    ],
};

const CONSENT_OPTIONS = [
    { value: 'Eligible', label: 'Eligible (Subscribed)' },
    { value: 'Unsubscribed', label: 'Unsubscribed (Opted-out)' },
    { value: 'Suppressed', label: 'Suppressed (Bounced/Blocked)' },
];

const MOCK_STORES = [
    { id: 'store_001', name: 'Flagship San Francisco' },
    { id: 'store_002', name: 'New York Boutique' },
    { id: 'store_003', name: 'London Outlet' },
    { id: 'store_004', name: 'Tokyo Concept' },
    { id: 'store_005', name: 'Online Store' },
];

// ============================================================================
// UTILS
// ============================================================================

function generateId(): string {
    return Math.random().toString(36).substring(2, 9);
}

function createEmptyRule(): SegmentRule {
    return { id: generateId(), field: 'last_order_days', operator: '>', value: '' };
}

// ============================================================================
// COMPONENT
// ============================================================================

interface SegmentRuleBuilderProps {
    value: SegmentRulesPayload;
    onChange: (payload: SegmentRulesPayload) => void;
}

export const SegmentRuleBuilder: React.FC<SegmentRuleBuilderProps> = ({ value, onChange }) => {
    const { logic, rules } = value;

    // ── Handlers ───────────────────────────────────────────────────────

    const updateRule = (id: string, patch: Partial<SegmentRule>) => {
        onChange({
            ...value,
            rules: rules.map((r) => {
                if (r.id !== id) return r;
                
                // If field changes, reset operator/value to defaults for that type
                if (patch.field && patch.field !== r.field) {
                    const newFieldCfg = FIELDS.find(f => f.value === patch.field)!;
                    const defaultOp = OPERATORS_FOR_TYPE[newFieldCfg.type][0].value;
                    const defaultValue = newFieldCfg.type === 'multi' ? [] : (newFieldCfg.type === 'select' ? 'Eligible' : '');
                    return { ...r, ...patch, operator: defaultOp, value: defaultValue };
                }
                
                return { ...r, ...patch };
            }),
        });
    };

    const addRule = () => {
        onChange({ ...value, rules: [...rules, createEmptyRule()] });
    };

    const removeRule = (id: string) => {
        if (rules.length <= 1) return;
        onChange({ ...value, rules: rules.filter((r) => r.id !== id) });
    };

    const toggleLogic = () => {
        onChange({ ...value, logic: logic === 'AND' ? 'OR' : 'AND' });
    };

    // ── Validation ────────────────────────────────────────────────────
    
    const errors = useMemo(() => {
        const errs: string[] = [];
        if (rules.length === 0) errs.push('At least one rule is required');
        rules.forEach((r, idx) => {
            if (Array.isArray(r.value)) {
                if (r.value.length === 0) errs.push(`Rule #${idx + 1} has no items selected`);
            } else if (!String(r.value).trim()) {
                errs.push(`Rule #${idx + 1} is missing a value`);
            }
        });
        return errs;
    }, [rules]);

    return (
        <div className="space-y-6">
            {/* Header */}
            <div className="flex items-center justify-between pb-2">
                <div className="flex items-center gap-3">
                    <div className="p-2 bg-indigo-50 rounded-xl text-indigo-600">
                        <Filter className="w-4 h-4" />
                    </div>
                    <div>
                        <h3 className="text-sm font-black text-slate-900 uppercase tracking-tight">Segmentation Protocol</h3>
                        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-0.5">Advanced targeting conditions</p>
                    </div>
                </div>
                {errors.length > 0 && (
                    <div className="flex items-center gap-2 px-3 py-1 bg-amber-50 border border-amber-100 rounded-full animate-pulse">
                        <AlertCircle className="w-3 h-3 text-amber-500" />
                        <span className="text-[10px] font-black text-amber-600 uppercase tracking-widest leading-none">Validation Pending</span>
                    </div>
                )}
            </div>

            {/* Logic Control */}
            <div className="flex items-center gap-6 p-1.5 bg-slate-50 border border-slate-200 rounded-[1.5rem] w-fit">
                <div className="flex bg-white p-1 rounded-xl shadow-sm border border-slate-100">
                    <button
                        onClick={() => logic !== 'AND' && toggleLogic()}
                        className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all
                            ${logic === 'AND' ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        Match All (AND)
                    </button>
                    <button
                        onClick={() => logic !== 'OR' && toggleLogic()}
                        className={`px-4 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all
                            ${logic === 'OR' ? 'bg-amber-500 text-white shadow-lg shadow-amber-100' : 'text-slate-400 hover:text-slate-600'}`}
                    >
                        Match Any (OR)
                    </button>
                </div>
                <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest pr-4 border-l border-slate-200 pl-4 h-5 flex items-center">
                    {logic === 'AND' ? 'Logical Intersection' : 'Logical Union'}
                </p>
            </div>

            {/* Rules Container */}
            <div className="space-y-3 relative">
                {rules.map((rule, idx) => {
                    const fieldCfg = FIELDS.find((f) => f.value === rule.field) || FIELDS[0];
                    const opOptions = OPERATORS_FOR_TYPE[fieldCfg.type];

                    return (
                        <div key={rule.id} className="relative group animate-in slide-in-from-left-2 duration-300" style={{ animationDelay: `${idx * 50}ms` }}>
                            {/* Connector Line */}
                            {idx > 0 && <div className="absolute -top-3 left-6 w-px h-3 bg-slate-100" />}

                            <div className={`p-4 bg-white border rounded-[1.5rem] shadow-sm flex flex-col md:flex-row items-start md:items-center gap-4 transition-all
                                ${String(rule.value || '').trim() ? 'border-slate-200' : 'border-amber-200/50 bg-amber-50/10'}`}>
                                
                                {/* 1. Field Selection */}
                                <div className="w-full md:w-[240px] shrink-0">
                                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1.5 ml-1">Condition Basis</label>
                                    <select
                                        value={rule.field}
                                        onChange={(e) => updateRule(rule.id, { field: e.target.value as SegmentField })}
                                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-xs font-black text-slate-900 focus:bg-white focus:border-indigo-500 focus:ring-4 focus:ring-indigo-50 outline-none transition-all appearance-none cursor-pointer"
                                    >
                                        {FIELDS.map((f) => <option key={f.value} value={f.value}>{f.label}</option>)}
                                    </select>
                                </div>

                                {/* 2. Operator Selection */}
                                <div className="w-full md:w-[180px] shrink-0">
                                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1.5 ml-1">Relationship</label>
                                    <select
                                        value={rule.operator}
                                        onChange={(e) => updateRule(rule.id, { operator: e.target.value as SegmentOperator })}
                                        className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-bold text-slate-600 focus:bg-white focus:border-indigo-500 outline-none transition-all appearance-none cursor-pointer"
                                    >
                                        {opOptions.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
                                    </select>
                                </div>

                                {/* 3. Value Input (Conditional) */}
                                <div className="flex-1 w-full min-w-0">
                                    <label className="block text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] mb-1.5 ml-1">Threshold / Target</label>
                                    
                                    {fieldCfg.type === 'select' ? (
                                        <select
                                            value={String(rule.value)}
                                            onChange={(e) => updateRule(rule.id, { value: e.target.value })}
                                            className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-black text-indigo-700 focus:bg-white outline-none transition-all appearance-none cursor-pointer"
                                        >
                                            {CONSENT_OPTIONS.map((c) => <option key={c.value} value={c.value}>{c.label}</option>)}
                                        </select>
                                    ) : fieldCfg.type === 'multi' ? (
                                        <MultiSelect
                                            options={MOCK_STORES}
                                            value={Array.isArray(rule.value) ? rule.value : []}
                                            onChange={(val) => updateRule(rule.id, { value: val })}
                                        />
                                    ) : (
                                        <div className="relative">
                                            <input
                                                type={fieldCfg.type === 'number' ? 'number' : 'text'}
                                                value={String(rule.value)}
                                                onChange={(e) => updateRule(rule.id, { value: e.target.value })}
                                                placeholder={fieldCfg.type === 'number' ? '0' : 'Enter value...'}
                                                className="w-full px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-black text-slate-900 focus:bg-white focus:border-indigo-500 outline-none transition-all placeholder:text-slate-300"
                                            />
                                            {fieldCfg.type === 'number' && (
                                                 <Hash className="absolute right-3 top-1/2 -translate-y-1/2 w-3 h-3 text-slate-300" />
                                            )}
                                        </div>
                                    )}
                                </div>

                                {/* 4. Actions */}
                                <div className="md:pt-4">
                                     <button
                                        onClick={() => removeRule(rule.id)}
                                        disabled={rules.length <= 1}
                                        className="p-3 text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-2xl transition-all disabled:opacity-0 disabled:pointer-events-none group-hover:bg-slate-50"
                                    >
                                        <Trash2 className="w-4 h-4" />
                                    </button>
                                </div>
                            </div>
                        </div>
                    );
                })}
            </div>

            {/* Rule Addition Block */}
            <div className="flex items-center gap-4 pt-4 relative">
                <button
                    onClick={addRule}
                    className="flex-1 flex items-center justify-center gap-2.5 py-4 border-2 border-dashed border-indigo-100 rounded-[2rem] text-[10px] font-black uppercase tracking-[0.2em] text-indigo-500 hover:border-indigo-500 hover:bg-indigo-50/50 hover:text-indigo-700 transition-all active:scale-95 group"
                >
                    <Plus className="w-4 h-4 transition-transform group-hover:rotate-90" /> Add Condition
                </button>
                
                <details className="hidden sm:block group">
                    <summary className="p-4 bg-slate-100 text-slate-400 rounded-full cursor-pointer hover:bg-slate-900 hover:text-white transition-all list-none outline-none shadow-sm ring-4 ring-white">
                         <Filter size={16} />
                    </summary>
                    <div className="absolute right-0 bottom-full mb-4 z-50">
                        <pre className="p-6 bg-slate-900 text-[10px] text-emerald-400 rounded-[2rem] shadow-[0_20px_50px_rgba(0,0,0,0.3)] border border-white/10 w-[320px] max-h-[400px] overflow-auto font-mono leading-relaxed animate-in zoom-in-95 origin-bottom-right">
                            <div className="flex items-center justify-between mb-4 pb-2 border-b border-white/10">
                                <span className="text-white font-black uppercase tracking-[0.2em]">Debug Context</span>
                                <div className="flex gap-1">
                                    <div className="w-1.5 h-1.5 rounded-full bg-rose-500" />
                                    <div className="w-1.5 h-1.5 rounded-full bg-amber-500" />
                                    <div className="w-1.5 h-1.5 rounded-full bg-emerald-500" />
                                </div>
                            </div>
                            {JSON.stringify(value, null, 2)}
                        </pre>
                    </div>
                </details>
            </div>

            {/* Validation Feedback */}
            {errors.length > 0 && (
                <div className="p-4 bg-amber-50 border border-amber-200 rounded-[1.5rem] flex items-start gap-3 mt-4 animate-in slide-in-from-top-2">
                    <AlertCircle className="w-4 h-4 text-amber-500 mt-0.5 shrink-0" />
                    <div>
                        <p className="text-[10px] font-black text-amber-900 uppercase tracking-widest leading-none mb-1">Incomplete Configuration</p>
                        <p className="text-[10px] text-amber-700 font-bold opacity-80 leading-relaxed uppercase tracking-tighter">Segment remains inactive until rules are validated</p>
                    </div>
                </div>
            )}
        </div>
    );
};

// ============================================================================
// AUXILIARY: MultiSelect Component
// ============================================================================

const MultiSelect: React.FC<{ options: any[], value: string[], onChange: (val: string[]) => void }> = ({ options, value, onChange }) => {
    const [open, setOpen] = useState(false);
    
    const toggle = (id: string) => {
        if (value.includes(id)) onChange(value.filter(v => v !== id));
        else onChange([...value, id]);
    };

    const selectedLabels = options.filter(o => value.includes(o.id)).map(o => o.name);

    return (
        <div className="relative">
            <button 
                type="button"
                onClick={() => setOpen(!open)}
                className="w-full flex items-center justify-between px-4 py-2.5 bg-slate-50 border border-slate-100 rounded-xl text-xs font-black text-indigo-700 text-left transition-all hover:bg-white"
            >
                <span className="truncate flex-1">
                    {value.length === 0 ? 'Select stores...' : value.length === 1 ? selectedLabels[0] : `${value.length} Stores Selected`}
                </span>
                <ChevronDown className={`w-3 h-3 ml-2 transition-transform ${open ? 'rotate-180' : ''}`} />
            </button>
            
            {open && (
                <>
                    <div className="fixed inset-0 z-40" onClick={() => setOpen(false)} />
                    <div className="absolute top-full left-0 right-0 mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl z-50 p-2 space-y-1 animate-in zoom-in-95 duration-200">
                        {options.map(o => (
                            <button
                                key={o.id}
                                onClick={() => toggle(o.id)}
                                className={`w-full flex items-center justify-between px-3 py-2 rounded-xl text-[10px] font-bold uppercase tracking-tight transition-all
                                    ${value.includes(o.id) ? 'bg-indigo-600 text-white' : 'text-slate-600 hover:bg-slate-50'}`}
                            >
                                {o.name}
                                {value.includes(o.id) && <Check size={12} />}
                            </button>
                        ))}
                        {value.length > 0 && (
                             <button
                                onClick={() => onChange([])}
                                className="w-full py-2 mt-2 border-t border-slate-100 text-[9px] font-black text-rose-500 uppercase tracking-widest text-center hover:bg-rose-50"
                             >
                                Clear Selection
                             </button>
                        )}
                    </div>
                </>
            )}
        </div>
    );
};

const Tooltip: React.FC<{ label: string; children: React.ReactNode }> = ({ label, children }) => {
    return (
        <div className="relative group/tt">
            {children}
            <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 px-3 py-1.5 bg-slate-900 text-white text-[10px] font-black uppercase tracking-widest rounded-lg opacity-0 group-hover/tt:opacity-100 transition-opacity whitespace-nowrap pointer-events-none z-50 shadow-xl">
                {label}
                <div className="absolute top-full left-1/2 -translate-x-1/2 border-4 border-transparent border-t-slate-900" />
            </div>
        </div>
    );
};

export default SegmentRuleBuilder;
